// CSD_RATIONALE_BEGIN
// Attempt 37: Fix the no-op penalty phase that caused attempt 9's 20% to be
// the ceiling.  Diagnostics ("Applied penalty: 0.5%") confirm that
// SafePenalizedConstrainedStep with ["C", "CC", "O"] is a near no-op because
// those strings are not Qwen3.5 BPE vocabulary tokens.  Attempt 9's first-6-
// token phase therefore reduced to plain ConstrainedStep (no temperature),
// while tokens 6-17 used T=1.6 and tokens 18+ used GroupBoosted.
//
// Root-cause ledger:
//   Attempt 36 (4%): Added "O=C=N" check alongside "N=C=O" → closes at first
//     complete parse → always the same short molecule → only 4 unique.
//   Attempt 35 (7%): NCO-only but minSpanLength=8 and T=1.8 → similar
//     collapse; larger minSpanLength blocks short valid structures.
//   Attempt 9 (20% best): NCO-only check + minSpanLength=5 + T=1.6 (tokens
//     6-17).  The NCO-only check is *intentional*: O=C=N... format SMILES
//     never contain "N=C=O" as a substring, so the model keeps generating
//     past the first complete parse, and CloseSpanWithinBudget finds a diverse
//     last-complete-prefix point.
//
// This attempt keeps the winning invariants from attempt 9:
//   • NCO-only check ("N=C=O" substring), never "O=C=N"
//   • minSpanLength = 5
//   • CloseSpanWithinBudget fallback
// And improves one dimension:
//   • Replace the no-op SafePenalizedConstrainedStep with
//     SafeTemperatureConstrainedStep(T=1.8) for ALL tokens < 30.
//     Higher temperature across all early tokens (not just 6-17) widens
//     the first-token distribution, producing more unique starting
//     structures and hence more unique final molecules.
//   • Guidance shows more diverse O=C=N... examples (30+ classes) so the
//     LM has a richer prior to draw from.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   OpenConstrainedSpan branch: sets currentConstrainedOut := [];
//     parser.IsValidPrefix([]) holds by method precondition. ✓
//   "Complete + hasNCO" branch → CloseConstrainedSpan: sets
//     insideConstrainedOut := false, making the implication vacuous, and
//     currentConstrainedOut := []. ✓
//   "Complete + no hasNCO" branch → SafeTemperatureConstrainedStep: hard-
//     masks to parser-valid tokens plus EOS; AppendConstrainedToken
//     postcondition preserves IsValidPrefix(currentConstrainedOut). ✓
//   "Not complete, tokenCount < 30" branch → SafeTemperatureConstrainedStep:
//     same hard-mask guarantee; AppendConstrainedToken preserves validity. ✓
//   "Not complete, tokenCount >= 30" branch → GroupBoostedConstrainedStep:
//     same hard-mask guarantee; AppendConstrainedToken preserves validity. ✓
//   EOS with valid close → CloseConstrainedSpan: sets insideConstrainedOut
//     := false. ✓
//   EOS without close → break: state unchanged, invariant preserved. ✓
//   Post-loop CloseSpanWithinBudget: postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
//   OpenConstrainedSpan: +1 to |generated| (for "<<"), +1 to steps. ✓
//   "Complete + hasNCO" → CloseConstrainedSpan: +1 to |generated| (for ">>"),
//     +1 to steps (within-bound because while condition guarantees
//     steps < maxSteps before the call). ✓
//   "Complete + no hasNCO" → step + AppendConstrainedToken: +1 to |generated|
//     (one token), +1 to steps; EOS adds 0 to |generated|, +1 to steps. ✓
//   "Not complete" branch: same argument as above. ✓
//   EOS → CloseConstrainedSpan sub-branch: the constrained step already
//     incremented steps; CloseConstrainedSpan guarded by steps < maxSteps
//     before the extra increment; total ≤ maxSteps. ✓
//   Post-loop: closeBudget = maxSteps - steps; CloseSpanWithinBudget
//     postcondition gives |cg| ≤ |generated| + closeBudget ≤
//     |generatedPrefix| + maxSteps; steps := maxSteps ≤ maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES for a novel isocyanate molecule (must contain N=C=O group). Use O=C=N... format. Be maximally structurally diverse across classes: alkyl (O=C=NCCC, O=C=NCCCC, O=C=NCCCCC, O=C=NCCCCCC, O=C=NCCCCCCC), branched (O=C=NC(C)C, O=C=NC(C)(C)C, O=C=NCC(C)C, O=C=NCC(CC)C, O=C=NC(CC)CC, O=C=NCC(C)(C)C), haloalkyl (O=C=NCC(F)(F)F, O=C=NCCCl, O=C=NCCBr, O=C=NCCF, O=C=NCCC(F)(F)F, O=C=NCCCCl, O=C=NCF, O=C=NCCl), cyclic (O=C=NC1CCC1, O=C=NC1CCCC1, O=C=NC1CCCCC1, O=C=NC1CCCCCC1, O=C=NC1CC1), aryl (O=C=Nc1ccccc1, O=C=NCc1ccccc1, O=C=Nc1ccc(F)cc1, O=C=Nc1ccc(Cl)cc1, O=C=Nc1cccc(C)c1, O=C=Nc1ccc(C)cc1, O=C=NCCc1ccccc1), heteroaryl (O=C=Nc1ccccn1, O=C=Nc1ccncc1, O=C=Nc1cccnc1, O=C=Nc1cnccn1), oxygenated (O=C=NCCOC, O=C=NCCO, O=C=NCOCC, O=C=NCCOCCO), sulfur (O=C=NCCS, O=C=NCCSC), unsaturated (O=C=NCC=C, O=C=NCC#C, O=C=NC=C). Output ONLY the SMILES string.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 5;
var tokenCount: nat := 0;

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      // N=C=O format confirmed: close the span immediately
      var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      steps := steps + 1;
    } else {
      // O=C=N format (no "N=C=O" substring): keep generating for diversity.
      // CloseSpanWithinBudget will find the last valid complete prefix.
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;
    if tokenCount < 30 {
      // All early tokens: high temperature for maximum structural diversity
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
    } else {
      // Late phase: group-boosted for valid grammar completion
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
        var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
        if hasNCO > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
    tokenCount := tokenCount + 1;
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

